#!/usr/bin/env python3
"""Generate R352 modules by cloning the template file with targeted line replacements."""

import re

def clone_module(template_path, replacements):
    """Read template, apply replacements, ensure exactly 253 lines (wc -l)."""
    with open(template_path, 'r') as f:
        content = f.read()
    
    for old, new in replacements.items():
        content = content.replace(old, new)
    
    # Ensure exactly 253 newlines (wc -l = 253)
    nl_count = content.count('\n')
    if nl_count < 253:
        content += '\n' * (253 - nl_count)
    elif nl_count > 253:
        # Trim from end
        lines = content.split('\n')
        content = '\n'.join(lines[:253]) + '\n' * (253 - 253 + 1) if lines[252] else '\n'.join(lines[:252]) + '\n'
        # Simpler: take first 253 lines
        content = '\n'.join(lines[:253])
        # Ensure exactly 253 newlines
        if content.count('\n') != 253:
            content = content.rstrip('\n') + '\n' * 254
            # Trim to 253
            content = content[:content.index('\n' * 253) + 253]
    
    return content

